import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const I=JSON.parse('{"title":"联机UI演进专题","description":"","frontmatter":{},"headers":[],"relativePath":"引擎更新/专题研究/联机UI演进专题.md","filePath":"引擎更新/专题研究/联机UI演进专题.md","lastUpdated":1777893104000}'),h={name:"引擎更新/专题研究/联机UI演进专题.md"};function d(n,l,o,u,p,c){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="联机ui演进专题" tabindex="-1">联机UI演进专题 <a class="header-anchor" href="#联机ui演进专题" aria-label="Permalink to “联机UI演进专题”">​</a></h1><ul><li>分类：引擎更新专题</li><li>子系统：联机UI / 当前UI / 上传并等待 / 广播架构 / 兼容迁移</li><li>关键词标签：联机UI, 当前UI, 上传并等待, 地图广播, 玩家.当前UI, 运行在本地, 20FPS</li><li>来源类型：引擎更新截图 OCR + 版本知识索引归纳</li><li>证据等级：截图直接证据 + 多版本交叉整理</li><li>完整度状态：深度整理</li><li>对应 OCR 文档：<code>docs/OCR资料/引擎更新截图转文本.md</code></li><li>来源截图编号：<code>105506, 105508, 105510, 105513, 105515, 105516, 105537</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>关联专题：<code>docs/引擎更新/引擎更新知识索引.md</code></li><li>最后更新：2026-04-20</li></ul><p>本文基于 <code>docs/引擎更新/引擎更新知识索引.md</code> 中 4.52.1、4.52.54、4.54.0 等版本内容，整理联机 UI 的演进脉络，并尝试从设计目标、性能问题、推荐写法三个角度做更深入的归纳。</p><h2 id="_1-为什么联机-ui-是一个独立研究主题" tabindex="-1">1. 为什么联机 UI 是一个独立研究主题 <a class="header-anchor" href="#_1-为什么联机-ui-是一个独立研究主题" aria-label="Permalink to “1. 为什么联机 UI 是一个独立研究主题”">​</a></h2><p>从现有版本更新记录看，联机 UI 并不是一次小修小补，而是创游世界近几个版本中非常明显的一条演进主线。</p><p>它涉及：</p><ul><li>UI 运行位置</li><li>玩家本地与公共数据的边界</li><li>上传并等待机制</li><li>当前 UI 的访问方式</li><li>推荐的广播驱动逻辑</li></ul><p>这说明 UI 在联机场景下并不只是显示问题，而是：</p><ul><li>架构问题</li><li>同步问题</li><li>性能问题</li><li>调用边界问题</li></ul><hr><h2 id="_2-旧-ui-逻辑的大致特征" tabindex="-1">2. 旧 UI 逻辑的大致特征 <a class="header-anchor" href="#_2-旧-ui-逻辑的大致特征" aria-label="Permalink to “2. 旧 UI 逻辑的大致特征”">​</a></h2><p>根据更新说明，旧逻辑的核心特点是：</p><ul><li>每个玩家设备会模拟所有玩家的 UI 逻辑</li><li>为了维持同步，帧率受到限制</li><li>复杂 UI、多人 UI、动画 UI 更容易卡顿</li></ul><h3 id="这意味着什么" tabindex="-1">这意味着什么 <a class="header-anchor" href="#这意味着什么" aria-label="Permalink to “这意味着什么”">​</a></h3><p>旧逻辑本质上更偏向：</p><ul><li>强同步</li><li>高耦合</li><li>为一致性牺牲流畅度</li></ul><p>问题在于：</p><ul><li>UI 越复杂，成本越高</li><li>玩家越多，负担越大</li><li>如果还在 UI 内频繁操作公共数据，就更慢</li></ul><hr><h2 id="_3-新-ui-逻辑的核心变化" tabindex="-1">3. 新 UI 逻辑的核心变化 <a class="header-anchor" href="#_3-新-ui-逻辑的核心变化" aria-label="Permalink to “3. 新 UI 逻辑的核心变化”">​</a></h2><p>新逻辑强调：</p><ul><li>每个玩家只运行自己的 UI</li><li>UI 更像“本地自治界面”</li><li>公共数据操作需要显式同步</li></ul><p>这是一个非常关键的转变：</p><ul><li>旧模式：大家都在模拟大家的 UI</li><li>新模式：每个人管自己的 UI，公共部分另外处理</li></ul><h3 id="架构意义" tabindex="-1">架构意义 <a class="header-anchor" href="#架构意义" aria-label="Permalink to “架构意义”">​</a></h3><p>这相当于把 UI 从“全局同步显示体”转为：</p><ul><li>本地显示层</li><li>本地交互层</li><li>需要时再和公共逻辑通讯</li></ul><hr><h2 id="_4-为什么会出现-上传并等待" tabindex="-1">4. 为什么会出现“上传并等待” <a class="header-anchor" href="#_4-为什么会出现-上传并等待" aria-label="Permalink to “4. 为什么会出现“上传并等待””">​</a></h2><p>更新说明里已经给出直接线索：</p><ul><li>当 UI 脚本去操作地图或玩家公共数据时，需要同步给其他玩家</li><li>每次同步大约需要一个等待成本</li></ul><p>所以“上传并等待”不是无缘无故的卡顿，而是系统在告诉你：</p><ul><li>你正在跨越本地 UI 层与公共数据层的边界</li><li>这一步需要网络同步或一致性处理</li></ul><h3 id="本质理解" tabindex="-1">本质理解 <a class="header-anchor" href="#本质理解" aria-label="Permalink to “本质理解”">​</a></h3><p>可以把它理解为：</p><ul><li>本地逻辑很快</li><li>公共逻辑较贵</li><li>跨层越频繁，整体越慢</li></ul><hr><h2 id="_5-官方推荐模式背后的真正含义" tabindex="-1">5. 官方推荐模式背后的真正含义 <a class="header-anchor" href="#_5-官方推荐模式背后的真正含义" aria-label="Permalink to “5. 官方推荐模式背后的真正含义”">​</a></h2><p>官方推荐：</p><ul><li>UI 向地图发一次广播</li><li>地图集中处理公共数据</li><li>UI 自己处理界面内部逻辑</li></ul><p>表面看像一个“写法建议”，本质上其实是在推动更清晰的系统分层：</p><h3 id="ui-层" tabindex="-1">UI 层 <a class="header-anchor" href="#ui-层" aria-label="Permalink to “UI 层”">​</a></h3><p>负责：</p><ul><li>接输入</li><li>做显示</li><li>播局部动画</li><li>响应当前玩家操作</li></ul><h3 id="地图层" tabindex="-1">地图层 <a class="header-anchor" href="#地图层" aria-label="Permalink to “地图层”">​</a></h3><p>负责：</p><ul><li>公共数据</li><li>联机同步相关规则</li><li>多对象共享流程</li></ul><h3 id="广播层" tabindex="-1">广播层 <a class="header-anchor" href="#广播层" aria-label="Permalink to “广播层”">​</a></h3><p>负责：</p><ul><li>在 UI 与地图之间传递意图</li><li>把直接耦合改成事件式协作</li></ul><hr><h2 id="_6-玩家-当前ui-到-当前ui-的变化意味着什么" tabindex="-1">6. <code>玩家.当前UI</code> 到 <code>当前UI</code> 的变化意味着什么 <a class="header-anchor" href="#_6-玩家-当前ui-到-当前ui-的变化意味着什么" aria-label="Permalink to “6. 玩家.当前UI 到 当前UI 的变化意味着什么”">​</a></h2><p>这是一个很值得研究的信号。</p><h3 id="表面变化" tabindex="-1">表面变化 <a class="header-anchor" href="#表面变化" aria-label="Permalink to “表面变化”">​</a></h3><ul><li>名称更短了</li><li>调用方式更新了</li></ul><h3 id="更深层变化" tabindex="-1">更深层变化 <a class="header-anchor" href="#更深层变化" aria-label="Permalink to “更深层变化”">​</a></h3><p>它暗示出：</p><ul><li>“当前 UI”正在被视为一个更直接、更标准的运行上下文</li><li>UI 的访问模型被重新定义</li><li>地图脚本不再被鼓励直接深控 UI 内部</li></ul><p>随后又推荐：</p><ul><li>玩家向当前 UI 发广播</li></ul><p>这说明系统更倾向于：</p><ul><li>通过消息通知 UI</li><li>而不是跨层直接改 UI 内部细节</li></ul><p>这是明显的架构收口行为。</p><hr><h2 id="_7-联机-ui-的设计原则" tabindex="-1">7. 联机 UI 的设计原则 <a class="header-anchor" href="#_7-联机-ui-的设计原则" aria-label="Permalink to “7. 联机 UI 的设计原则”">​</a></h2><p>结合现有资料，可以总结出几条很实用的原则。</p><h3 id="原则-1-让-ui-偏本地化" tabindex="-1">原则 1：让 UI 偏本地化 <a class="header-anchor" href="#原则-1-让-ui-偏本地化" aria-label="Permalink to “原则 1：让 UI 偏本地化”">​</a></h3><p>UI 优先处理：</p><ul><li>动画</li><li>局部显示</li><li>玩家自己的操作反馈</li></ul><h3 id="原则-2-把公共状态处理下沉到地图" tabindex="-1">原则 2：把公共状态处理下沉到地图 <a class="header-anchor" href="#原则-2-把公共状态处理下沉到地图" aria-label="Permalink to “原则 2：把公共状态处理下沉到地图”">​</a></h3><p>凡是会影响：</p><ul><li>所有人</li><li>公共数据</li><li>共享流程</li></ul><p>都尽量交给地图层。</p><h3 id="原则-3-用广播传意图-不要直接跨层硬控" tabindex="-1">原则 3：用广播传意图，不要直接跨层硬控 <a class="header-anchor" href="#原则-3-用广播传意图-不要直接跨层硬控" aria-label="Permalink to “原则 3：用广播传意图，不要直接跨层硬控”">​</a></h3><p>这样：</p><ul><li>更清晰</li><li>更稳定</li><li>更适合联机</li></ul><h3 id="原则-4-区分-显示正确-和-同步正确" tabindex="-1">原则 4：区分“显示正确”和“同步正确” <a class="header-anchor" href="#原则-4-区分-显示正确-和-同步正确" aria-label="Permalink to “原则 4：区分“显示正确”和“同步正确””">​</a></h3><p>有些逻辑本地看起来没问题，但联机下可能不同步。</p><p>所以联机 UI 设计必须同时考虑：</p><ul><li>视觉流畅</li><li>数据一致</li></ul><hr><h2 id="_8-兼容选项与版本演进说明了什么" tabindex="-1">8. 兼容选项与版本演进说明了什么 <a class="header-anchor" href="#_8-兼容选项与版本演进说明了什么" aria-label="Permalink to “8. 兼容选项与版本演进说明了什么”">​</a></h2><p>更新说明提到：</p><ul><li>老联机项目可以通过兼容选项切换</li><li>新项目默认使用新逻辑</li><li>且新逻辑可能无法回退</li></ul><p>这说明：</p><ul><li>官方认为新逻辑不是实验功能，而是方向性升级</li><li>UI 运行模型已经发生真正的代际变化</li><li>老项目迁移时必须做专门验证</li></ul><p>这也提醒知识库后续要非常重视：</p><ul><li>版本条件</li><li>兼容模式</li><li>老项目迁移成本</li></ul><hr><h2 id="_9-对知识库建设的意义" tabindex="-1">9. 对知识库建设的意义 <a class="header-anchor" href="#_9-对知识库建设的意义" aria-label="Permalink to “9. 对知识库建设的意义”">​</a></h2><p>联机 UI 主题非常适合做成长线专题，因为它同时连着：</p><ul><li>UI 系统</li><li>广播机制</li><li>数据同步</li><li>版本兼容</li><li>运行性能</li></ul><p>未来如果继续补更多更新截图，完全可以把它做成：</p><ul><li>版本时间线</li><li>推荐写法演进图</li><li>常见错误模式集合</li><li>单机/联机对照指南</li></ul><hr><h2 id="_10-适合-ai-rag-的关键词" tabindex="-1">10. 适合 AI/RAG 的关键词 <a class="header-anchor" href="#_10-适合-ai-rag-的关键词" aria-label="Permalink to “10. 适合 AI/RAG 的关键词”">​</a></h2><ul><li>联机UI</li><li>当前UI</li><li>玩家.当前UI</li><li>向当前UI发广播</li><li>上传并等待</li><li>UI 本地运行</li><li>UI 同步</li><li>地图处理</li><li>UI 架构</li><li>兼容选项</li><li>20FPS</li><li>UI 重构</li></ul><hr><h2 id="_11-后续可继续深挖的问题" tabindex="-1">11. 后续可继续深挖的问题 <a class="header-anchor" href="#_11-后续可继续深挖的问题" aria-label="Permalink to “11. 后续可继续深挖的问题”">​</a></h2><ol><li>新旧 UI 逻辑在具体脚本行为上的差异清单</li><li>哪些 UI 操作属于纯显示，哪些会触发同步</li><li>地图广播与当前 UI 广播的最佳配合方式</li><li>联机 UI 中最常见的性能陷阱</li><li>老项目迁移到新 UI 逻辑的排查清单</li></ol>',100)])])}const U=i(h,[["render",d]]);export{I as __pageData,U as default};
